 4. script.js (egyszerű 3D háttér, mint a mintán)

js
// Egyszerű 3D pontfelhő animáció canvas-on
const canvas = document.getElementById('bg');
const ctx = canvas.getContext('2d');
let w, h, points = [];

function resize() {
  w = window.innerWidth;
  h = window.innerHeight;
  canvas.width = w;
  canvas.height = h;
}
resize();
window.addEventListener('resize', resize);

function randomPoint() {
  return {
    x: Math.random() * w,
    y: Math.random() * h,
    z: Math.random() * 200 + 50,
    dx: (Math.random() - 0.5) * 0.8,
    dy: (Math.random() - 0.5) * 0.8,
    dz: (Math.random() - 0.5) * 0.2
  };
}

for(let i=0; i<60; i++) points.push(randomPoint());

function draw() {
  ctx.clearRect(0,0,w,h);
  for(let p of points) {
    // 3D perspektíva
    let scale = 200 / (p.z);
    let px = (p.x - w/2) * scale + w/2;
    let py = (p.y - h/2) * scale + h/2;
    ctx.beginPath();
    ctx.arc(px, py, 3*scale, 0, 2*Math.PI);
    ctx.fillStyle = `rgba(0,212,255,${0.3+0.7*scale})`;
    ctx.fill();
    // Mozgatás
    p.x += p.dx; p.y += p.dy; p.z += p.dz;
    if(p.x<0||p.x>w) p.dx*=-1;
    if(p.y<0||p.y>h) p.dy*=-1;
    if(p.z<50||p.z>250) p.dz*=-1;
  }
  requestAnimationFrame(draw);
}
draw();




 5. Telepítés Repliten

1. Hozz létre egy új Replit projektet (HTML, CSS, JS template).
2. Másold be a fenti három fájlt.
3. Indítsd el a replt, és máris láthatod az oldalad!



 Megjegyzés

 A fenti háttér egy egyszerűbb, de látványos 3D hatású pontfelhő, ami hasonlít az eredeti oldal animációjára.
 Ha szeretnél még fejlettebb 3D effekteket (pl. háromszögek, WebGL), ajánlom a three.js könyvtárat, de az már összetettebb.
 A színek, szövegek, linkek szabadon módosíthatók!

Így már tényleg hasonlít a mintára, és könnyen továbbfejleszthető! Ha szeretnéd, segítek még three.jsszel vagy extra effektekkel is.
